self.__next_f.push([1,"2b:[[\"$\",\"p\",null,{\"children\":[\"The Text Generation Web UI is a Gradio-based interface for running Large Language Models like LLaMA, llama.cpp, GPT-J, Pythia, OPT, and GALACTICA.\\nIt provides a user-friendly interface to interact with these models and generate text, with features such as model switching, notebook mode, chat mode, and more.\\nThe project aims to become the go-to web UI for text generation and is similar to \",[\"$\",\"a\",null,{\"href\":\"https://github.com/AUTOMATIC1111/stable-diffusion-webui\",\"rel\":\"noopener noreferrer nofollow\",\"target\":\"_blank\",\"children\":\"AUTOMATIC1111/stable-diffusion-webui\"}],\" in terms of functionality.\"]}],\"\\n\",[\"$\",\"h2\",null,{\"id\":\"features\",\"children\":\"Features\"}],\"\\n\",[\"$\",\"ul\",null,{\"children\":[\"\\n\",[\"$\",\"li\",null,{\"children\":\"Dropdown menu for switching between models\"}],\"\\n\",[\"$\",\"li\",null,{\"children\":\"Notebook mode that resembles OpenAI's playground\"}],\"\\n\",[\"$\",\"li\",null,{\"children\":\"Chat mode for conversation and role-playing\"}],\"\\n\",[\"$\",\"li\",null,{\"children\":\"Instruct mode compatible with various formats, including Alpaca, Vicuna, Open Assistant, Dolly, Koala, ChatGLM, and MOSS\"}],\"\\n\",[\"$\",\"li\",null,{\"children\":\"Nice HTML output for GPT-4chan\"}],\"\\n\",[\"$\",\"li\",null,{\"children\":\"Markdown output for GALACTICA, including LaTeX rendering\"}],\"\\n\",[\"$\",\"li\",null,{\"children\":\"Custom chat characters\"}],\"\\n\",[\"$\",\"li\",null,{\"children\":\"Advanced chat features (send images, get audio responses with TTS)\"}],\"\\n\",[\"$\",\"li\",null,{\"children\":\"Efficient text streaming\"}],\"\\n\",[\"$\",\"li\",null,{\"children\":\"Parameter presets\"}],\"\\n\",[\"$\",\"li\",null,{\"children\":\"Layers splitting across GPU(s), CPU, and disk\"}],\"\\n\",[\"$\",\"li\",null,{\"children\":\"CPU mode\"}],\"\\n\",[\"$\",\"li\",null,{\"children\":\"and much more!\"}],\"\\n\"]}],\"\\n\",[\"$\",\"h2\",null,{\"id\":\"installation\",\"children\":\"Installation\"}],\"\\n\",[\"$\",\"p\",null,{\"children\":[\"There are different installation methods available, including one-click installers for Windows, Linux, and macOS, as well as manual installation using Conda. Detailed installation instructions can be found in the \",[\"$\",\"a\",null,{\"href\":\"https://github.com/oobabooga/text-generation-webui\",\"rel\":\"noopener noreferrer nofollow\",\"target\":\"_blank\",\"children\":\"Text Generation Web UI repository\"}],\".\"]}],\"\\n\",[\"$\",\"h2\",null,{\"id\":\"downloading-models\",\"children\":\"Downloading Models\"}],\"\\n\",[\"$\",\"p\",null,{\"children\":[\"Models should be placed inside the \",[\"$\",\"code\",null,{\"className\":\"$undefined\",\"children\":\"models\"}],\" folder. You can download models from \",[\"$\",\"a\",null,{\"href\":\"https://huggingface.co/models?pipeline_tag=text-generation\u0026sort=downloads\",\"rel\":\"noopener noreferrer nofollow\",\"target\":\"_blank\",\"children\":\"Hugging Face\"}],\", such as Pythia, OPT, GALACTICA, and GPT-J 6B. Use the \",[\"$\",\"code\",null,{\"className\":\"$undefined\",\"children\":\"download-model.py\"}],\" script to automatically download a model from Hugging Face.\"]}],\"\\n\",[\"$\",\"h2\",null,{\"id\":\"starting-the-web-ui\",\"children\":\"Starting the Web UI\"}],\"\\n\",[\"$\",\"p\",null,{\"children\":[\"After installing the necessary dependencies and downloading the models, you can start the web UI by running the \",[\"$\",\"code\",null,{\"className\":\"$undefined\",\"children\":\"server.py\"}],\" script. The web UI can be accessed at \",[\"$\",\"code\",null,{\"className\":\"$undefined\",\"children\":\"http://localhost:7860/?__theme=dark\"}],\". You can customize the interface and behavior using various command-line flags.\"]}],\"\\n\",[\"$\",\"h2\",null,{\"id\":\"system-requirements\",\"children\":\"System Requirements\"}],\"\\n\",[\"$\",\"p\",null,{\"children\":[\"Check the \",[\"$\",\"a\",null,{\"href\":\"https://github.com/oobabooga/text-generation-webui/wiki\",\"rel\":\"noopener noreferrer nofollow\",\"target\":\"_blank\",\"children\":\"wiki\"}],\" for examples of VRAM and RAM usage in both GPU and CPU mode.\"]}],\"\\n\",[\"$\",\"h2\",null,{\"id\":\"contributing\",\"children\":\"Contributing\"}],\"\\n\",[\"$\",\"p\",null,{\"children\":\"Pull requests, suggestions, and issue reports are welcome. Before reporting a bug, make sure you have followed the installation instructions provided and searched for existing issues.\"}]]\n"])